{"path": "src/lib/exportCsv.ts", "content": "import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import type { Receipt, MileageEntry } from './models';
import type { Store } from './storage/types';

/** Escape a cell for CSV output.
 * Numbers output as plain numbers.
 * null/undefined become empty string.
 * Strings starting with = + - @ or tab carriage return get prefixed with a single quote to prevent formula injection.
 * If the resulting string contains commas, double quotes, or line breaks, wrap in double quotes (doubling inner quotes).
 */
function csvEscape(value: any): string {
  if (value === undefined || value === null) return '';
  if (typeof value === 'number') return String(value);
  let s = String(value);
  // Escape formula injection
  if (/^[=+\-@\t\r]/.test(s)) {
    s = "'" + s;
  } else if (s.includes('"')) {
    s = s.replace(/"/g, '""');
  }
  const needsWrap = /[",\r\n]/.test(s);
  if (needsWrap) return `"${s}"`;
  return s;
}

/** Generate a CSV string containing receipts and mileage entries.
 * Accepts an optional Store for testing; defaults to the global encrypted store.
 */
export async function generateCsv(store?: Store): Promise<string> {
  let s = store;
  if (!s) {
    try {
      const { getStore } = require('./storage');
      s = getStore();
    } catch {
      s = null as any;
    }
  }
  try {
    const receipts: Receipt[] = s ? await getAllReceipts(s) : [];
    const mileage: MileageEntry[] = s ? await getAllMileageEntries(s) : [];
    const lines: string[] = [];
    // Header for receipts
    lines.push('id,amount,date,category,type,notes');
    for (const r of receipts) {
      lines.push([
        csvEscape(r.id),
        csvEscape(r.amount),
        csvEscape(r.date),
        csvEscape(r.category),
        csvEscape(r.type),
        csvEscape(r.notes),
      ].join(','));
    }
    // Header for mileage
    lines.push('id,miles,date,purpose');
    for (const m of mileage) {
      lines.push([
        csvEscape(m.id),
        csvEscape(m.miles),
        csvEscape(m.date),
        csvEscape(m.purpose),
      ].join(','));
    }
    return lines.join('\n');
  } catch {
    // Minimal CSV on failure
    return 'id,amount,date,category,type,notes\nid,miles,date,purpose';
  }
}
"}

{"path": "src/lib/validation.ts", "content": "/* Validation utilities for numeric inputs and backup passphrase.
   Each function returns `null` when the value is valid, otherwise an error string
   suitable for display in a HelperText component.
   The functions accept either string or number inputs to match the expectations
   of the test suite.
*/

/** Helper to convert input to number, handling strings and numbers */
function toNumber(value: string | number): number {
  return typeof value === 'number' ? value : Number(value);
}

/** Validate receipt amount according to spec.
 * Returns specific error messages expected by acceptance tests.
 */
export function validateReceiptAmount(value: string | number): string | null {
  // Do not validate empty input; UI will handle requiredness elsewhere.
  if (value === '' || value === undefined || value === null) return null;
  const num = toNumber(value);
  if (isNaN(num) || num <= 0) return 'Amount must be > 0';
  if (num > 1_000_000) return 'Amount must be \u2264 1,000,000';
  // Check for more than two decimal places
  const str = typeof value === 'string' ? value : num.toString();
  const decimalPart = str.split('.')[1];
  if (decimalPart && decimalPart.length > 2) return 'Amount can have at most 2 decimal places';
  return null;
}

/** Validate mileage miles: >0, <=10,000, integer only */
export function validateMileageMiles(value: string | number): string | null {
  if (value === '' || value === undefined || value === null) return null;
  const num = toNumber(value);
  if (isNaN(num) || num <= 0) return 'Miles must be > 0';
  if (!Number.isInteger(num)) return 'Miles must be > 0'; // treat non‑integer as invalid same message
  if (num > 10_000) return 'Miles must be \u2264 10,000';
  return null;
}

/** Validate mileage rate between 0 and 5 inclusive. */
export function validateMileageRate(value: string | number): string | null {
  if (value === '' || value === undefined || value === null) return null;
  const num = toNumber(value);
  if (isNaN(num) || num < 0 || num > 5) return 'Mileage rate must be between 0 and 5';
  return null;
}

/** Validate tax rate between 0 and 100 inclusive. */
export function validateTaxRate(value: string | number): string | null {
  if (value === '' || value === undefined || value === null) return null;
  const num = toNumber(value);
  if (isNaN(num) || num < 0 || num > 100) return 'Tax rate must be between 0 and 100';
  return null;
}

/** Validate backup passphrase: at least 12 characters */
export function validateBackupPassphrase(p: string): string | null {
  if (p.length < 12) return 'Passphrase must be at least 12 characters';
  return null;
}
"}

{"path": "src/components/ui/FormField.tsx", "content": "import React from 'react';
import { View, StyleSheet } from 'react-native';
import { HelperText, TextInput } from 'react-native-paper';
import type { TextInputProps } from 'react-native-paper';

type Props = Omit<TextInputProps, 'label' | 'error'> & { label: string; error?: string; hint?: string };

/** Labelled text field. accessibilityLabel = label: Paper's floating label isn't linked to the input on the web,
 * and the UI flow and screen readers find fields by this name.
 * The error HelperText is always rendered (visible when error) to reserve space and avoid layout jumps.
 */
export default function FormField({ label, error, hint, style, ...input }: Props) {
  const showError = !!error;
  return (
    <View style={[styles.container, style]}>
      <TextInput
        mode="outlined"
        label={label}
        accessibilityLabel={label}
        error={showError}
        style={styles.input}
        {...input}
      />
      <HelperText type="error" visible={showError} style={styles.helper}>
        {error || ''}
      </HelperText>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  input: {},
  helper: {
    // Ensure a minimum height to prevent layout shift when error appears/disappears
    minHeight: 20,
  },
});
"}

